import Foundation
import KwipMLCore

/// Presentation over public task metadata. Never reads assessment fixtures or computes answers.
@MainActor enum TensorTopicLessonCopy {
    struct TaskCopy {let purpose:String;let sources:String;let wiring:String;let controls:String;let question:String}
    static func task(_ operation:String)->TaskCopy? {
        if let t=SpatialPatchLearningTask(rawValue:operation) {
            let purpose=t.isUnfold ? "A sliding image operation repeatedly reads small neighboring rectangles. Unfold makes those rectangles explicit as columns so another calculation can process each patch." : "Patch calculations may need to place their results back on a grid. Fold adds contributions that land on the same position; it cannot guess values where no patch reaches."
            let sources=t.isUnfold ? "Input supplies two channels, each with three rows and four columns per observation. Channels are separate grids. A patch selects nearby cells within those grids." : "Input supplies packed patch columns with sample shape \(t.sampleShape). Each column contains one patch's channel and cell values. The requested output has sample shape \(t.outputSampleShape)."
            return .init(purpose:purpose,sources:sources,wiring:"Add Input, \(t.isUnfold ? "Unfold":"Fold") and Model Output. Connect Input.out → \(t.isUnfold ? "Unfold":"Fold").in, then \(t.isUnfold ? "Unfold":"Fold").out → Model Output.in.",controls:t.controlInstructions,question:t.isUnfold ? "Which source cells appear in more than one patch? Why does adding a zero border change the visited positions without inventing measurements?":"Why does overlap add rather than average? Which output positions remain zero when no patch reaches them?")
        }
        if let t=TensorRoutingLearningTask(rawValue:operation) {
            let purposes:[TensorRoutingLearningTask:String]=[
                .splitSize:"A feature table may contain consecutive groups that another layer needs in a different order. Split names the groups so you can reconnect the intended parts explicitly.",
                .splitSections:"Feature groups need not have equal widths. Choose their section sizes, then reconnect the named parts without losing a value.",
                .chunk:"Requesting six chunks does not guarantee six actual outputs when equal chunk widths leave fewer parts. Inspect the final uneven part instead of assuming the last requested port exists.",
                .gather:"A table of positions can select values from another table. Repeated positions deliberately reuse a source value; those selectors are data, not configuration recipes.",
                .einsumCombine:"Matrix-style combination compares each left row with each right column: multiply paired values and add the products. Einsum's preset names that arrangement without requiring notation.",
                .einsumDiagonal:"Sometimes the values of interest lie on a square table's diagonal. Select matching row/column positions without mixing the other cells."
            ]
            let sources=t.sourceRoles.map {"- \($0): sample shape \(t.sampleShapes[$0] ?? [])."}.joined(separator:"\n")
            let wiring:String
            switch t {
            case .splitSize,.splitSections:wiring="Add Input, Split tensor, two Concatenate blocks and Model Output. Connect Input.out → Split tensor.in. The part ports feed the Concatenate inputs in the order below; the final Concatenate.out connects to Model Output.in."
            case .chunk:wiring="Add Input, Split tensor and Model Output. Choose Method → Request chunks on Split tensor. Connect Input.out → Split tensor.in; connect only the selected part to Model Output.in."
            case .gather:wiring="Add the number Input and Position selectors, then Gather and Model Output. Connect number output → source and selector output → indices; connect Gather.out → Model Output.in."
            case .einsumCombine:wiring="Add the left and right Inputs, Einsum and Model Output. Connect left.out → a and right.out → b; connect Einsum.out → Model Output.in."
            case .einsumDiagonal:wiring="Add Input, Einsum and Model Output. Connect Input.out → a and Einsum.out → Model Output.in."
            }
            let controls=t.controlInstructions.replacingOccurrences(of:"Split mode to size",with:"Split mode to Equal-sized parts").replacingOccurrences(of:"Split mode to sections",with:"Split mode to Chosen section sizes").replacingOccurrences(of:"Arrangement preset to multiply",with:"Arrangement preset to Combine tables").replacingOccurrences(of:"Arrangement preset to diagonal",with:"Arrangement preset to Read a diagonal")
            return .init(purpose:purposes[t]!,sources:"The checker supplies these roles for each observation:\n"+sources+"\nThe requested output sample shape is \(t.outputSampleShape). Positions count from zero; shapes are counts, not position numbers.",wiring:wiring,controls:controls,question:t == .gather ? "If a selector repeats one position twice, how many times is that source value used? Why must selector IDs stay whole numbers?":"Which source positions feed the result, and in what order? Explain why rejoining selected parts is different from reshaping the same reading order.")
        }
        if let t=TensorCompositionLearningTask(rawValue:operation) {
            let purpose:String
            switch t {
            case .concat:purpose="Two feature paths may describe the same observation. Concatenate appends one path along an existing direction; every other direction must remain compatible."
            case .add:purpose="A shared three-value correction can be applied to each row of an observation. Add combines corresponding values instead of appending more features."
            case .stack:purpose="Two equally shaped sources can stay distinguishable by occupying a new source direction. Stack retains both arrays instead of adding them together."
            case .permute:purpose="A layer may need the same values with directions in a different order. Transpose's Reorder axes method moves coordinates; it does not read the numbers into a new shape as Reshape would."
            }
            let sources="The left input has sample shape \(t.leftSampleShape)."+(t.rightSampleShape.map {" The right input has sample shape \($0)."} ?? " There is no second source.")+" The required output sample shape is \(t.outputSampleShape)."
            let wiring=t.isBinary ? "Add the two Inputs, \(t == .concat ? "Concatenate":t == .add ? "Add":"Stack") and Model Output. Connect left.out → a and right.out → b, then the result out → Model Output.in." : "Add Input, Transpose and Model Output. Choose Method → Reorder axes. Connect Input.out → Transpose.in, then Transpose.out → Model Output.in."
            return .init(purpose:purpose,sources:sources,wiring:wiring,controls:t.controlInstructions,question:t == .stack ? "Which direction identifies the source? How would Concatenate produce a different shape?":t == .add ? "Why does reusing the right pattern in two rows add its influence twice? Which values must remain separate between observations?":"What changes: values, coordinates, or the number of positions? Trace one source value to its result before submitting.")
        }
        switch operation {
        case "reshape","transpose","flatten":
            let purpose=operation == "reshape" ? "A layer may need the same six features in a new arrangement. Reshape changes their grouping while preserving reading order within each observation." : operation == "transpose" ? "A table's rows and columns can represent different roles. Swapping their directions changes each value's coordinates while keeping the original values." : "A later layer may need one feature row instead of a small table. Flatten combines selected directions without combining different observations."
            let controls=operation == "reshape" ? "Add Reshape and choose Method → Set dimensions. Set Sample dimensions to [3, 2]." : operation == "transpose" ? "Add Transpose and choose Method → Swap axes. Set First axis to 1 and Second axis to 2." : "Add Reshape and choose Method → Flatten axes. Set First axis to 1 and Last axis to -1. The last axis is included; -1 means the final direction."
            let block=operation == "transpose" ? "Transpose":"Reshape"
            return .init(purpose:purpose,sources:"Each observation starts as two rows with three numbers per row: sample shape [2, 3]. The requested sample shape is \(operation == "flatten" ? "[6], one row of six features":"[3, 2], three rows of two numbers"). The leading batch dimension counts observations and is separate from these sample dimensions.",wiring:"The canvas starts empty. Add Input, \(block) and Model Output, then connect Input.out → \(block).in and \(block).out → Model Output.in.",controls:controls,question:"Starting with rows [1, 2, 3] and [4, 5, 6], where would 2 appear? This tiny illustration is a prediction aid, not the checker's captured input. Why should another observation's numbers never enter this result?")
        case "matrix-contraction","matrix-broadcast-gradients":
            return .init(purpose:"Two numeric tables can combine by multiplying a row from the first with a column from the second and adding the paired products. This is the calculation behind many learned feature projections.",sources:operation == "matrix-broadcast-gradients" ? "The checker supplies left and right tables with compatible inner dimensions and additional grouping directions. A grouping size of 1 can be reused within the same observation; this is broadcasting." : "The checker supplies a left and a right table for each observation. The left column count must equal the right row count. The result keeps the left row count and right column count.",wiring:"Add left and right Inputs, Matrix multiply and Model Output. Connect left.out → a, right.out → b and Matrix multiply.out → Model Output.in.",controls:"Matrix multiply has no calculation settings. Prepare the operands and connect the correct roles. Do not transpose, scale or normalize them to conceal a shape mismatch. Inspect the public required shapes for this task; the checker also varies compatible sizes.",question:"For illustration, row [1, 2] and column [3, 4] combine as 1×3 + 2×4 = 11. Which dimension disappears? When a table is reused, why should contributions return to its original shape?")
        case "bilinear-with-bias","bilinear-without-bias":
            let bias=operation == "bilinear-with-bias"
            return .init(purpose:"Some predictions depend on interactions between two feature sets. Bilinear weights a pair of features together; simply appending the two feature rows would not perform that pairwise calculation.",sources:"The checker supplies Left operand, Right operand and Shared weights."+(bias ? " Shared bias supplies one offset per output feature.":" This task has no bias input.")+" These are mathematical source roles in the restricted assessment, not workflow configuration recipes. Observation and grouping dimensions must match exactly.",wiring:"Add the supplied-role Inputs, Bilinear and Model Output. Connect Left operand → a, Right operand → b, Shared weights → weight"+(bias ? " and Shared bias → bias":"")+". Connect Bilinear.out → Model Output.in.",controls:bias ? "This task fixes Learned bias on. Keep the supplied bias input connected. Use the other library assessment to work without bias." : "This task fixes Learned bias off. Do not add a bias input. Use the other library assessment to include it.",question:"Why do the interaction weights have left-feature and right-feature directions? How does a shared offset differ from another observation's data? The checker supplies the weights; do not enter calculated answers.")
        default:return nil
        }
    }
    static func exampleSteps(_ id:String)->[LessonContentStep]? {
        if id=="tensor-example" {
            return [
                LessonContent.step("goal","Follow the same features through new layouts","A classifier may need its features in several layouts. In this supplied workflow, a learned Linear projection produces twelve features, Reshape groups them into three rows of four, Transpose swaps them to four rows of three, and Flatten returns them to one row before the final classifier.\n\nThe canvas is already populated. Table Input and preparation produce numeric observations; Model input starts the model path and Train learns from Training while measuring Validation. The layout operations themselves add no learned weights and do not create new feature values."),
                LessonContent.step("build","Trace one observation","1. Find the twelve-feature projection in the model path.\n2. Follow its output through Reshape, Transpose and Flatten.\n3. Compare each declared sample shape, keeping the observation direction separate.\n\nThree rows of four and four rows of three both contain twelve numbers, but their coordinates differ.",kind:.canvasAction),
                LessonContent.step("layout.run","Inspect the captured order","Run Flow, then select each layout component's captured Output. Trace a few values across the tables. Reshape preserves reading order; Transpose changes coordinates; Flatten reads the current coordinate order into one direction.\n\nUse Reshape → Method → Flatten axes for a new Flatten placement, and Transpose → Swap axes or Reorder axes for coordinate changes. Apply changes and rerun before comparing evidence.",kind:.canvasAction),
                LessonContent.step("inspect","Explain the model's capacity","Which blocks actually learned weights? Why do layout changes alone not add a nonlinear response? Compare Train's captured Validation predictions separately from intermediate tensor layouts.\n\nThis is an editable, unscored example. The separate Construction tasks test mathematical behavior without exposing private fixture tables.",kind:.question)
            ]
        }
        if id=="matrix-example" {
            return [
                LessonContent.step("goal","Learn two interacting feature tables","Two views of the same observation can interact through matrix multiplication rather than only being appended. This example learns both operands, then uses their row–column products for classification.\n\nOpen matrix example in Exercise choices & reference to load its supplied workflow; the initial lesson canvas is empty. Save existing work before replacing it.\n\nFollow Measurements into two Linear paths:\n- Learn left matrices produces 24 features, arranged as two 3-by-4 heads. A head is one parallel table.\n- Learn shared right matrix produces 8 features, arranged as a 4-by-2 table reused across those heads.\n- Row–column interactions produces two 3-by-2 result tables, twelve features in total.\n- Flatten and Class scores turn those results into two class scores for Train.\n\nThis demonstrates feature interaction, not a complete attention architecture."),
                LessonContent.step("build","Inspect both operands","1. Open the supplied example below.\n2. Follow the two model paths into Matrix multiply's a and b ports.\n3. Check their shared size 4: the left column count equals the right row count.\n\nThe right operand is shared across heads within each observation. It is not copied from another observation.",kind:.canvasAction),
                LessonContent.step("matrix.run","Run and compare shapes and values","Run Flow and inspect Row–column interactions → Output. The sample result is [2, 3, 2]: two heads, three rows, two columns. N in a full shape is a separate observation count.\n\nFor a small illustration, row [1, 2] and column [3, 4] produce 1×3 + 2×4 = 11. Compare actual captured rows and columns rather than treating that illustration as the model's output. Matrix multiply adds no weights; the upstream Linear layers learn the operands.",kind:.canvasAction),
                LessonContent.step("inspect","Separate interaction from prediction","Which two learned paths influence one product? Why does a shared operand receive contributions from each head that uses it? Inspect Train's captured Validation predictions to evaluate the classifier.\n\nThis workflow is editable and unscored; a correct shape does not establish prediction quality.",kind:.question)
            ]
        }
        return nil
    }
    static func steps(_ operation:String)->[LessonContentStep]? {
        guard let copy=task(operation) else {return nil}
        return [
            .init(id:"goal",title:"Meet the construction",blocks:[
                .init(id:"goal.body",kind:.explanation,title:"Understand the idea",text:copy.purpose+"\n\nThis is a Construction assessment. Its canvas starts without the completed transformation; the checker supplies varied input numbers when you submit. You are configuring the calculation, not training a predictor or importing a dataset."),
                .init(id:"goal.sources",kind:.explanation,title:"Understand the supplied inputs",text:copy.sources+"\n\nA sample shape describes one observation. Axis 0 in a full tensor counts observations; later axes describe that sample. Keep observations separate.")]),
            LessonContent.step("build.0","Connect the calculation",copy.wiring+"\n\nUse the restricted toolbar. A named port identifies the role of a connection. Reading Next does not add or connect components.",kind:.canvasAction),
            LessonContent.step("build.1","Configure the transformation",copy.controls+"\n\nApply pending fields before submitting. Planned shapes describe configuration; they are not measured output values.",kind:.canvasAction),
            LessonContent.step("build.2","Predict before submitting",copy.question,kind:.question),
            LessonContent.step("check","Submit and read the feedback","Choose Submit assessment in Check your construction. The existing checker tests output behavior and small-change influence on independent inputs. Influence, also called a gradient, describes how a small input change affects the result; you do not calculate derivatives or enter gradient answers.\n\nRead the measured criteria feedback and repair the indicated setting or connection. Private assessment fixture tables stay hidden. An unavailable or cancelled check is different from an incorrect result. Completion requires a passing current assessment and its saved receipt; edits make an earlier result historical.",kind:.observation)
        ]
    }
}
